{
  "claims": [
    {
      "claim_id": "c1",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [0] explicitly states that the WAL option is available beginning with version 3.7.0.",
      "citations": [
        {
          "index": 0,
          "quote": "Beginning with version 3.7.0 (2010-07-21), a new \"Write-Ahead Log\" option (hereafter referred to as \"WAL\") is available."
        }
      ]
    },
    {
      "claim_id": "c2",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [3] confirms that writers and readers can run simultaneously in WAL mode because writers do not interfere with readers.",
      "citations": [
        {
          "index": 3,
          "quote": "Because writers do nothing that would interfere with the actions of readers, writers and readers can run at the same time."
        }
      ]
    },
    {
      "claim_id": "c3",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [3] explicitly states that there can only be one writer at a time due to the single WAL file.",
      "citations": [
        {
          "index": 3,
          "quote": "However, since there is only one WAL file, there can only be one writer at a time."
        }
      ]
    },
    {
      "claim_id": "c4",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [2] states that SQLite performs an automatic checkpoint when the WAL file reaches a threshold of 1000 pages by default.",
      "citations": [
        {
          "index": 2,
          "quote": "By default, SQLite does a checkpoint automatically when the WAL file reaches a threshold size of 1000 pages."
        }
      ]
    },
    {
      "claim_id": "c5",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [4] describes the naming convention for the WAL file as usually being the database file name with a '-wal' suffix.",
      "citations": [
        {
          "index": 4,
          "quote": "The name of this file on disk is usually the name of the database file with a extra \"-wal\" suffix"
        }
      ]
    }
  ]
}

{
  "claims": [
    {
      "claim_id": "c1",
      "verdict": "SUPPORTED",
      "reasoning": "The first sentence of passage [0] explicitly states that WAL works best with smaller transactions.",
      "citations": [
        {
          "index": 0,
          "quote": "WAL works best with smaller transactions."
        }
      ]
    },
    {
      "claim_id": "c2",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage [0] states that traditional rollback journal modes will likely be faster for transactions larger than about 100 megabytes, not 10 megabytes as claimed.",
      "citations": [
        {
          "index": 0,
          "quote": "For transactions larger than about 100 megabytes, traditional rollback journal modes will likely be faster."
        }
      ]
    },
    {
      "claim_id": "c3",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [0] explicitly mentions that for transactions in excess of a gigabyte, WAL mode may fail with an I/O or disk-full error.",
      "citations": [
        {
          "index": 0,
          "quote": "For transactions in excess of a gigabyte, WAL mode may fail with an I/O or disk-full error."
        }
      ]
    },
    {
      "claim_id": "c4",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [1] states that WAL might be very slightly slower (perhaps 1% or 2% slower) than the traditional rollback-journal approach in applications that do mostly reads.",
      "citations": [
        {
          "index": 1,
          "quote": "WAL might be very slightly slower (perhaps 1% or 2% slower) than the traditional rollback-journal approach in applications that do mostly reads and seldom write."
        }
      ]
    },
    {
      "claim_id": "c5",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [2] explains that write transactions are very fast since they only involve writing the content once.",
      "citations": [
        {
          "index": 2,
          "quote": "Write transactions are very fast since they only involve writing the content once"
        }
      ]
    }
  ]
}

{
"claims": [
    {
        "claim_id": "c1",
        "verdict": "SUPPORTED",
        "reasoning": "The passage explicitly states that a checkpoint can run concurrently with readers.",
        "citations": [
            {
                "index": 0,
                "quote": "A checkpoint can run concurrently with readers"
            }
        ]
    },
    {
        "claim_id": "c2",
        "verdict": "SUPPORTED",
        "reasoning": "The passage explicitly states the condition under which a checkpoint must stop regarding the reader's end mark.",
        "citations": [
            {
                "index": 0,
                "quote": "the checkpoint must stop when it reaches a page in the WAL that is past the end mark of any current reader."
            }
        ]
    },
    {
        "claim_id": "c3",
        "verdict": "SUPPORTED",
        "reasoning": "The passage directly states that a long-running read transaction can prevent the checkpointer from making progress.",
        "citations": [
            {
                "index": 1,
                "quote": "Thus a long-running read transaction can prevent a checkpointer from making progress."
            }
        ]
    },
    {
        "claim_id": "c4",
        "verdict": "CONTRADICTED",
        "reasoning": "The passage states that if there is always at least one active reader, no checkpoints will be able to complete, contradicting the claim that they still complete.",
        "citations": [
            {
                "index": 3,
                "quote": "if a database has many concurrent overlapping readers and there is always at least one active reader, then no checkpoints will be able to complete"
            }
        ]
    },
    {
        "claim_id": "c5",
        "verdict": "CONTRADICTED",
        "reasoning": "The passage states that the disadvantage of using these options is that readers might block, contradicting the claim that they are never blocked.",
        "citations": [
            {
                "index": 4,
                "quote": "The disadvantage of using SQLITE_CHECKPOINT_RESTART and SQLITE_CHECKPOINT_TRUNCATE is that readers might block while the checkpoint is running."
            }
        ]
    },
    {
        "claim_id": "c6",
        "verdict": "UNSUPPORTED",
        "reasoning": "While the passages explain that checkpoint starvation causes WAL file growth, they do not state that it is the 'most common cause' in production systems.",
        "citations": []
    }
]
}

{
  "claims": [
    {
      "claim_id": "c1",
