    {
      "claim_id": "c3",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [1] states that applications can be converted to WAL mode without making changes to the application itself.",
      "citations": [
        {
          "index": 1,
          "quote": "The persistence of WAL mode means that applications can be converted to using SQLite in WAL mode without making any changes to the application itself."
        }
      ]
    },
    {
      "claim_id": "c4",
      "verdict": "UNSUPPORTED",
      "reasoning": "The provided passages do not contain any information regarding the release date of SQLite WAL mode.",
      "citations": []
