    {
      "claim_id": "c5",
      "verdict": "UNSUPPORTED",
      "reasoning": "The provided passages do not mention Android or default journal modes for specific platforms.",
      "citations": []
    },
    {
      "claim_id": "c6",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [3] explicitly states that the WAL file is part of the persistent state and should be kept with the database if copied or moved.",
      "citations": [
        {
          "index": 3,
